{{-- Feature spot: chat — conversation with messages, typing indicator and an email notification. Theme-aware; ids are prefixed with $uid. --}}
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 140" fill="none"><defs><filter id="{{ $uid }}-sh" x="-30%" y="-30%" width="160%" height="190%"><feDropShadow dx="0" dy="4" stdDeviation="5" flood-color="var(--ill-shadow)"/></filter><radialGradient id="{{ $uid }}-ga"><stop offset="0" stop-color="#6366F1" stop-opacity=".26"/><stop offset="1" stop-color="#6366F1" stop-opacity="0"/></radialGradient><radialGradient id="{{ $uid }}-gb"><stop offset="0" stop-color="#22D3EE" stop-opacity=".22"/><stop offset="1" stop-color="#22D3EE" stop-opacity="0"/></radialGradient><pattern id="{{ $uid }}-dots" width="10" height="10" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8" fill="var(--ill-line)"/></pattern><linearGradient id="{{ $uid }}-gi" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#6366F1"/><stop offset="1" stop-color="#4F46E5"/></linearGradient><linearGradient id="{{ $uid }}-gv" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#8B5CF6"/><stop offset="1" stop-color="#6366F1"/></linearGradient><linearGradient id="{{ $uid }}-gc" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#3B82F6"/><stop offset="1" stop-color="#22D3EE"/></linearGradient><linearGradient id="{{ $uid }}-ge" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#10B981"/><stop offset="1" stop-color="#22D3EE"/></linearGradient></defs><rect width="200" height="140" rx="16" fill="var(--ill-canvas)"/><rect width="200" height="140" rx="16" fill="url(#{{ $uid }}-dots)" opacity=".75"/><circle cx="50" cy="52" r="72" fill="url(#{{ $uid }}-ga)"/><circle cx="162" cy="100" r="64" fill="url(#{{ $uid }}-gb)"/><rect x="16" y="20" width="98" height="30" rx="13" fill="var(--ill-panel)" stroke="var(--ill-line)" filter="url(#{{ $uid }}-sh)"/><circle cx="29" cy="35" r="7.5" fill="url(#{{ $uid }}-gc)"/><rect x="42" y="28.5" width="56" height="3.5" rx="1.8" fill="var(--ill-text)" opacity=".55"/><rect x="42" y="36.5" width="40" height="3" rx="1.5" fill="var(--ill-line)"/><rect x="72" y="58" width="104" height="30" rx="13" fill="url(#{{ $uid }}-gi)" filter="url(#{{ $uid }}-sh)"/><rect x="84" y="66" width="64" height="3.5" rx="1.8" fill="#fff" opacity=".92"/><rect x="84" y="74" width="44" height="3" rx="1.5" fill="#fff" opacity=".6"/><path d="M150 79 l2 2 l4 -4.5 M155 81 l4 -4.5" stroke="#A5F3FC" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" fill="none"/><rect x="16" y="96" width="44" height="24" rx="12" fill="var(--ill-panel)" stroke="var(--ill-line)" filter="url(#{{ $uid }}-sh)"/><circle cx="28" cy="108" r="2.8" fill="var(--ill-muted)" class="ill-pulse ill-delay-1"/><circle cx="38" cy="108" r="2.8" fill="var(--ill-muted)" class="ill-pulse ill-delay-2"/><circle cx="48" cy="108" r="2.8" fill="var(--ill-muted)" class="ill-pulse ill-delay-3"/><g class="spot-float"><rect x="142" y="16" width="40" height="28" rx="6" fill="var(--ill-panel)" stroke="var(--ill-line)" filter="url(#{{ $uid }}-sh)"/><path d="M143.5 19 L162 32 L180.5 19" stroke="#6366F1" stroke-width="1.8" stroke-linejoin="round" fill="none"/><circle cx="181" cy="17" r="6" fill="#10B981" opacity=".35" class="ill-ping"/><circle cx="181" cy="17" r="4" fill="#10B981" stroke="var(--ill-canvas)" stroke-width="1.5"/></g></svg>
